INSERT INTO game_entities(timeline_id,id,kind,name,visibility,data_json,created_at,updated_at)
SELECT t.id,
 lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))),2) || '-a' || substr(lower(hex(randomblob(2))),2) || '-' || lower(hex(randomblob(6))),
 'skill',s.name,'campaign',s.data_json,
 strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now')
FROM timelines t CROSS JOIN background_skills s
WHERE NOT EXISTS (SELECT 1 FROM game_entities e WHERE e.timeline_id=t.id AND e.kind='skill' AND e.name=s.name);
